int build_path(const char *directory, const char *filename, char *path) {
    // Check if the directory and filename are not NULL
    if (directory == NULL || filename == NULL || path == NULL) {
        return -1;
    }

    // Copy the directory to the path buffer
    strncpy(path, directory, MAX_PATH - 1);
    path[MAX_PATH - 1] = '\0';  // Ensure null-termination

    // Check if the path buffer has enough space for the filename
    if (strlen(path) + strlen(filename) + 2 > MAX_PATH) {
        return -1;
    }

    // Append the filename to the path buffer
    strcat(path, "/");
    strcat(path, filename);

    return 0;
}
