void itoa(int num, char *str) {
    if (num == 0) {
        *str = '\0';
        return;
    }
    int sign = 1;
    if (num < 0) {
        num = -num;
        sign = -1;
    }
    int len = 0;
    while (num!= 0) {
        str[len++] = (num % 10) + '0';
        num /= 10;
    }
    if (sign == -1) {
        str[len++] = '-';
    }
    while (len < MAX_BUFFER_LEN - 1) {
        str[len++] ='';
    }
    str[len] = '\0';
}

int item_to_string(Item *item, char *str) {
    itoa(item->quantity, str);
    sprintf(str + strlen(str), " x %s @ $%.2f ea", item->name, item->price);
}
