void list_item_to_string(node *head, char *str) {
    int quantity = 0;
    char item_name[MAX_ITEM_PRINT_LEN];
    float price = 0.0;
    char price_str[8];

    strcpy(str, "");

    if (head == NULL) {
        return;
    }

    quantity = head->quantity;
    strcpy(item_name, head->item_name);

    sprintf(price_str, "%.2f", head->price);
    strcat(str, itoa(quantity));
    strcat(str, " x ");
    strcat(str, item_name);
    strcat(str, " @ $");
    strcat(str, price_str);

    if (head->next!= NULL) {
        node *temp = head;
        while (temp->next!= NULL) {
            temp = temp->next;
            quantity += temp->quantity;
            strcat(str, ", ");
            strcat(str, itoa(quantity));
            strcat(str, " x ");
            strcpy(item_name, temp->item_name);
            sprintf(price_str, "%.2f", temp->price);
            strcat(str, item_name);
            strcat(str, " @ $");
            strcat(str, price_str);
        }
    }
}
