int build_path(const char *directory, const char *filename, char *path) {
    // Check if directory and filename are not NULL
    if (directory == NULL || filename == NULL) {
        return -1;  // Return error code
    }

    // Check if path buffer is large enough
    if (strlen(directory) + strlen(filename) + 2 >= MAX_PATH) {
        return -1;  // Return error code
    }

    // Copy the directory path to the buffer
    strcpy(path, directory);

    // Check if the directory does not end with a path separator
    if (path[strlen(path) - 1]!= '/' && path[strlen(path) - 1]!= '\\') {
        // Append a path separator
        path[strlen(path)] = '/';
        path[strlen(path) + 1] = '\0';  // Null-terminate the string
    }

    // Append the filename to the buffer
    strcat(path, filename);

    return 0;  // Return success code
}
