    size_t dir_len = strlen(directory);
    size_t filename_len = strlen(filename);
    size_t max_len = dir_len + filename_len + 2; // +2 for the '/' and '\0'

    // Check if the path buffer is large enough
    if (max_len >= MAX_PATH) {
        return -1; // or some other error code
    }

    // Copy the directory to the path buffer
    snprintf(path, MAX_PATH, "%s/", directory);

    // Check if the directory ended with a '/'
    if (path[MAX_PATH - 2]!= '/') {
        // Add a '/' if it doesn't exist
        path[MAX_PATH - 1] = '/';
        path[MAX_PATH] = '\0';
