void itoa(int num, char *str) {
    if (num == 0) {
        *str = '\0';
        return;
    }
    int i, sign;
    if ((sign = num) < 0) {
        num = -num;
    }
    i = 0;
    do {
        str[i++] = num % 10 + '0';
    } while ((num /= 10) > 0);
    if (sign < 0) {
        str[i++] = '-';
    }
    while (i < MAX_BUFFER_LEN - 1) {
        str[i++] = '0';
    }
    str[i] = '\0';
}

