int build_path(const char *directory, const char *filename, char *path) {
    // Check for null pointer arguments
    if (directory == NULL || filename == NULL || path == NULL) {
        return -1;
    }

    // Check if the path buffer is large enough
    if (strlen(directory) + strlen(filename) + 2 > MAX_PATH) {
        return -1;
