void log_message(const char *message, char *buffer) {
    if (message == NULL) {
        // If message is NULL, return immediately
        return;
    }

    // Calculate the available space in the buffer
    size_t available_space = BUFFER_SIZE - 1; // Leave one byte for the null terminator

    // Copy the message to the buffer
    strncpy(buffer, message, available_space);

    // Null-terminate the buffer
    buffer[available_space] = '\0';

    // If the message is longer than the buffer, append an ellipsis to the end
    if (strlen(message) > available_space) {
        // Calculate the length of the truncated message
        size_t truncated_length = available_space - 3; // Leave space for the ellipsis

        // Truncate the message and append an ellipsis
        strncpy(buffer, message, truncated_length);
        buffer[truncated_length] = '\0';
        strcat(buffer, "...");
    }
}
