```c
void log_message(const char *message, char *buffer) {
    // Validate the input buffer to prevent buffer overflows
    if (buffer == NULL || strlen(buffer) < BUFFER_SIZE) {
        fprintf(stderr, "Error: Invalid buffer provided for logging.\n");
        return;
    }

    // Validate the input message to prevent null pointer dereferences
    if (message == NULL) {
        fprintf(stderr, "Error: Null message provided for logging.\n");
        return;
    }

    // Use snprintf to safely write the message to the buffer
    // This prevents buffer overflows by specifying the maximum number of characters to write
    if (snprintf(buffer, BUFFER_SIZE, "%s", message) >= BUFFER_SIZE) {
        fprintf(stderr, "Error: Message too long for logging buffer.\n");
        return;
    }
}
