#define MAX_LINE_LEN 256

typedef struct _node {
    char *item_name;
    float price;
    int quantity;
    struct _node *next;
} node;

// save the list to file filename
// the file should be in the following format:
// item_name,price,quantity\n
int list_save(node *head, char *filename) {
    FILE *file = NULL;
    node *current = head;

    // Check if filename is NULL
    if (filename == NULL) {
        fprintf(stderr, "Error: filename is NULL\n");
        return -1;
    }

    // Open file in write mode
    if ((file = fopen(filename, "w")) == NULL) {
        fprintf(stderr, "Error: unable to open file '%s'\n", filename);
        return -1;
    }

    // Loop through linked list and write each node to file
    while (current!= NULL) {
        // Validate item_name to prevent buffer overflow
        if (current->item_name == NULL) {
            fprintf(stderr, "Error: item_name is NULL\n");
            fclose(file);
            return -1;
        }

        // Use snprintf to prevent buffer overflow
        char line[MAX_LINE_LEN];
        snprintf(line, sizeof(line), "%s,%.2f,%d\n", current->item_name, current->price, current->quantity);
        if (fputs(line, file) == EOF) {
            fprintf(stderr, "Error: unable to write to file '%s'\n", filename);
            fclose(file);
            return -1;
        }

        current = current->next;
    }

    fclose(file);
    return 0;
}
