// Build a full file path from directory and filename components
// Write the result to the provided path buffer
int build_path(const char *directory, const char *filename, char *path) {
    // Validate input lengths to prevent buffer overflow
    if (strlen(directory) >= MAX_PATH - strlen(filename) - 2) {
        // Directory name is too long
        return -1;
    }
    if (strlen(filename) >= MAX_PATH - strlen(directory) - 2) {
        // Filename is too long
        return -1;
    }

    // Use snprintf to safely construct the path
    // The %s format specifier will expand to the directory and filename
    // The maximum length is MAX_PATH - 2 to account for the '/' separator
    if (snprintf(path, MAX_PATH, "%s/%s", directory, filename) >= MAX_PATH) {
        // Path construction failed due to buffer overflow
        return -1;
    }

    return 0;
}
