void itoa(int num, char *str) {
    int sign = (num < 0)? -1 : 1;
    num = num * sign;

    int i = 0;
    do {
        str[i++] = (num % 10) + '0';
        num /= 10;
    } while (num);

    if (sign == -1)
        str[i++] = '-';

    while (i--)
        str[i] = str[i];

    str[i] = '\0';
}

