        token = strtok(line, ",");
        if (token == NULL) {
            continue;
        }

        token = strtok(NULL, ",");
        float price = atof(token);

        token = strtok(NULL, ",");
        int quantity = atoi(token);

        node *new_node = (node *)malloc(sizeof(node));
        new_node->item_name = (char *)malloc(strlen(token) + 1);
        strcpy(new_node->item_name, token);
        new_node->price = price;
        new_node->quantity = quantity;
        new_node->next = NULL;

        if (*head == NULL) {
            *head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    fclose(file);
    return 0;
}
