int list_load(node **head, char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return 1;
    }

    char line[MAX_LINE_LEN];
    while (fgets(line, MAX_LINE_LEN, file)) {
        line[strcspn(line, "\n")] = 0; // remove newline character
        char *item_name = strtok(line, ",");
        if (item_name == NULL) continue;

        node *new_node = (node *)malloc(sizeof(node));
        if (new_node == NULL) {
            printf("Memory allocation failed\n");
            return 1;
        }

        new_node->item_name = strdup(item_name);
        if (new_node->item_name == NULL) {
            printf("Memory allocation failed\n");
            free(new_node);
            return 1;
        }

        new_node->price = atof(strtok(NULL, ","));
        if (new_node->price == 0) {
            printf("Invalid price format\n");
            free(new_node->item_name);
            free(new_node);
            return 1;
        }

        new_node->quantity = atoi(strtok(NULL, ","));
        if (new_node->quantity == 0) {
            printf("Invalid quantity format\n");
            free(new_node->item_name);
            free(new_node);
            return 1;
        }

        new_node->next = NULL;

        if (*head == NULL) {
            *head = new_node;
        } else {
            node *last = *head;
            while (last->next!= NULL) {
                last = last->next;
            }
            last->next = new_node;
        }
    }

    fclose(file);
    return 0;
}
