    char *token;
    int field_count = 0;
    char *start = strdup(line);
    char *end = start;

    while (field_count < max_fields && (token = strtok_r(end, ",", &end))!= NULL) {
        if (field_count >= max_fields) {
            fprintf(stderr, "Error: Too many fields in CSV line\n");
            return -1;
