void safe_string_copy(char *dest, const char *src, size_t dest_size) {
    size_t src_len = strlen(src);
    if (src_len >= dest_size) {
        // If the source string is longer than the destination buffer, 
        // we cannot safely copy it without risking a buffer overflow
        // So, we return immediately and let the caller handle the error
        return;
    }

    // We use the safer strcpy_s function from the C11 standard
    // However, since this function is not available in older C standards, 
    // we will use strncpy_s from C11 and the _countof operator from C11
    #ifdef __STDC_VERSION__
        // C11
        if (strncpy_s(dest, dest_size, src, src_len)!= 0) {
            // If strncpy_s fails, it returns a non-zero value
            // We handle the error by returning immediately
            return;
        }
    #else
        // Older C standards
        strncpy(dest, src, src_len);
        dest[dest_size - 1] = '\0'; // Ensure null-termination
    #endif
}
