void safe_string_copy(char *dest, const char *src, size_t dest_size) {
    // Check if the destination buffer is null
    if (dest == NULL) {
        fprintf(stderr, "Error: Destination buffer is null\n");
        exit(EXIT_FAILURE);
    }

    // Check if the destination buffer size is valid
    if (dest_size == 0) {
        fprintf(stderr, "Error: Destination buffer size is zero\n");
        exit(EXIT_FAILURE);
    }

    // Check if the source string is null
    if (src == NULL) {
        *dest = '\0';
        return;
    }

    // Copy the source string into the destination buffer, up to the destination size - 1
    size_t src_len = strlen(src);
    if (src_len < dest_size - 1) {
        strncpy(dest, src, src_len);
        dest[src_len] = '\0';  // Ensure null-termination
    } else {
        // If the source string is longer than the destination buffer, truncate it
        strncpy(dest, src, dest_size - 1);
        dest[dest_size - 1] = '\0';  // Ensure null-termination
    }
}
