    if (dest == NULL || src == NULL || dest_size == 0) {
        return;
    }

    size_t src_len = strlen(src);
    if (src_len >= dest_size) {
        // If the source string is larger than the destination buffer, copy only up to the buffer size
        memcpy(dest, src, dest_size - 1);
        dest[dest_size - 1] = '\0';
    } else {
        // If the source string is smaller than the destination buffer, copy the entire source string
        memcpy(dest, src, src_len);
        dest[src_len] = '\0';
