        char *price_str = strtok(NULL, ",");
        char *quantity_str = strtok(NULL, "\n");

        if (item_name == NULL || price_str == NULL || quantity_str == NULL) {
            continue; // invalid line format
        }

        float price = atof(price_str);
        int quantity = atoi(quantity_str);

        // create new node
        node *new_node = malloc(sizeof(node));
        if (new_node == NULL) {
            fclose(file);
            return -2; // out of memory
        }

        new_node->item_name = malloc(strlen(item_name) + 1);
        if (new_node->item_name == NULL) {
            free(new_node);
            fclose(file);
            return -2; // out of memory
        }
        strcpy(new_node->item_name, item_name);

        new_node->price = price;
        new_node->quantity = quantity;
        new_node->next = NULL;

        if (*head == NULL) {
            *head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    fclose(file);
    return 0; // successful load
