#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LEN 256

typedef struct _node {
    char *item_name;
    float price;
    int quantity;
    struct _node *next;
} node;

// load the list from file filename
// the file is in the following format:
// item_name,price,quantity\n
int list_load(node **head, char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // unable to open file
    }

    node *current = NULL;
    node *new_node = NULL;

    char buffer[MAX_LINE_LEN];
    while (fgets(buffer, MAX_LINE_LEN, file)!= NULL) {
        // remove newline character from the end of the string
        buffer[strcspn(buffer, "\n")] = 0;

        char *item_name = strtok(buffer, ",");
        char *price_str = strtok(NULL, ",");
        char *quantity_str = strtok(NULL, "\n");

        if (item_name == NULL || price_str == NULL || quantity_str == NULL) {
            continue; // invalid line format
        }

        new_node = (node *)malloc(sizeof(node));
        if (new_node == NULL) {
            return -2; // out of memory
        }

        new_node->item_name = strdup(item_name);
        if (new_node->item_name == NULL) {
            free(new_node);
            return -2; // out of memory
        }

        new_node->price = atof(price_str);
        new_node->quantity = atoi(quantity_str);

        if (*head == NULL) {
            *head = new_node;
        } else {
            current = *head;
            while (current->next!= NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    fclose(file);
    return 0;
}
