    if (stream == NULL || response == NULL) {
        fprintf(stderr, "Error: Invalid input\n");
        exit(EXIT_FAILURE);
    }

    size_t length = strlen(response);
    if (length == 0) {
        fprintf(stderr, "Error: Response is empty\n");
        exit(EXIT_FAILURE);
    }

    if (fprintf(stream, "%s\n", response) < 0) {
        fprintf(stderr, "Error writing to stream\n");
        exit(EXIT_FAILURE);
    }
}
