    // Check if the status string is NULL to prevent potential crashes
    if (status == NULL) {
        fprintf(stderr, "Error: status string is NULL\n");
        return;
    }

    // Check if the status string is too long to prevent buffer overflow
    if (strlen(status) >= 1024) {
        fprintf(stderr, "Error: status string is too long (max 1024 characters)\n");
        return;
    }

    // Use snprintf to safely write the status message to the log file
