// Function to securely concatenate two strings
void secure_strcat(char *dest, const char *src, size_t dest_size) {
    if (dest == NULL || src == NULL || dest_size <= 0) {
        log_debug("Invalid arguments for secure_strcat");
        return;
    }

    size_t dest_len = strlen(dest);
    if (dest_len >= dest_size - strlen(src) - 1) {
        log_debug("Destination buffer too small for secure_strcat");
        return;
    }

    strncat(dest, src, dest_size - dest_len - 1);
    dest[dest_size - 1] = '\0';
}
