def delete_expired_sessions(db_path, expiry_date):
    try:
        expiry_date = expiry_date.strip()
        if not expiry_date:
            raise ValueError("Expiry date cannot be empty")

        try:
            expiry_date = datetime.datetime.strptime(expiry_date, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError("Invalid expiry date format. Use YYYY-MM-DD.")

        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            query = "DELETE FROM sessions WHERE expiry_date <?"
            cursor.execute(query, (expiry_date,))
            conn.commit()
            return cursor.rowcount
    except sqlite3.Error as e:
        print(f"Error deleting expired sessions: {e}")
        return 0
