        for rdata in answers:
            print(f"Name server: {rdata.target}")
        answers = dns.resolver.resolve(domain, 'SOA')
        for rdata in answers:
            print(f"Start of authority: {rdata.mname}")
            print(f"Serial number: {rdata.serial}")
            print(f"Refresh: {rdata.refresh}")
            print(f"Retry: {rdata.retry}")
            print(f"Expire: {rdata.expire}")
            print(f"Minimum TTL: {rdata.min_ttl}")
    except (dns.resolver.NoAnswer, dns.resolver.NXDOMAIN):
        print("No DNS records found for the domain.")
    except dns.resolver.NoNameservers:
        print("No nameservers available to resolve the domain.")
    except Exception as e:
        print(f"An error occurred: {e}")
