import subprocess
from pathlib import Path

def resize_image(input_path, output_path, size):
    if not isinstance(input_path, str) or not isinstance(output_path, str):
        raise TypeError("input_path and output_path must be strings")

    if not isinstance(size, tuple) or len(size)!= 2 or not all(isinstance(x, int) for x in size):
        raise TypeError("size must be a tuple of two integers")

    if size[0] <= 0 or size[1] <= 0:
        raise ValueError("Image dimensions must be positive integers")

    input_path = Path(input_path)
    output_path = Path(output_path)

    if not input_path.exists():
        raise FileNotFoundError(f"The input file '{input_path}' does not exist")

    if input_path.suffix.lower() not in ['.jpg', '.jpeg', '.png', '.gif', '.bmp']:
        raise ValueError(f"Unsupported image format: {input_path.suffix}")

    output_path.parent.mkdir(parents=True, exist_ok=True)

    command = ['convert', '-resize', f'{size[0]}x{size[1]', '-quality', '90', str(input_path), str(output_path)]
    try:
        subprocess.run(command, check=True)
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error resizing image: {e}")
        return False
```

