import subprocess

def list_processes(name_filter=None):
    if not isinstance(name_filter, str):
        raise TypeError("name_filter must be a string")

    if name_filter is None:
        command = ["ps", "-eo", "pid,ppid,comm"]
    else:
        command = ["ps", "-eo", "pid,ppid,comm"]
        command.append(f"name={name_filter}")

    try:
        output = subprocess.check_output(command).decode("utf-8")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to list processes: {e}")

    # Use a safer alternative to str.splitlines()
    lines = output.strip().splitlines()

    if not lines:
        return "No processes found"

    header = lines.pop(0)
    lines = [line.split() for line in lines]

    # Use a safer alternative to string formatting
    result = []
    for line in lines:
        result.append(f"PID: {line[0]}, PPID: {line[1]}, Name: {line[2]}")

    return "\n".join(result)
