def clone_repository(url, destination):
    # Validate the destination directory
    if not isinstance(destination, str) or not os.path.isabs(destination):
        raise ValueError("Destination must be an absolute path")

    # Check if the destination directory already exists
    if os.path.exists(destination):
        raise FileExistsError(f"Destination directory '{destination}' already exists")

    # Validate the repository URL
    if not isinstance(url, str) or not url.startswith('git@') and not url.startswith('https://') and not url.startswith('http://'):
        raise ValueError("Invalid repository URL")

    # Create the destination directory
    try:
        os.makedirs(destination, exist_ok=True)
    except OSError as e:
        raise OSError(f"Failed to create destination directory: {e}")

    # Use subprocess with list args to clone the repository safely
    try:
        subprocess.run(['git', 'clone', url, destination], check=True)
        return True
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to clone repository: {e}")
