        output = subprocess.check_output(["dig", "+short", domain], text=True)

        # Check for DNS lookup errors
        if output.startswith(";; connection timed out"):
            raise subprocess.CalledProcessError("DNS lookup timed out")
        elif output.startswith("; <<>> DiG 9.16.1-RC1-Debian <<>>"):
            raise subprocess.CalledProcessError("DNS lookup failed")

        # Parse the DNS lookup output
        ip_addresses = [line.strip() for line in output.splitlines() if line.strip()]

        return ip_addresses

    except subprocess.CalledProcessError as e:
        raise ValueError(f"DNS lookup failed: {e}")
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")
```

