        if 'title' not in result or 'link' not in result or 'description' not in result:
            raise ValueError("Each result must have 'title', 'link', and 'description' keys")

        html_string += "<li><a href='{}'>{}</a>: {}</li>".format(
            html.escape(result['link']),
            html.escape(result['title']),
            html.escape(result['description'])
        )

    html_string += "</ul></body></html>"

