    html_message = "<h1>Error</h1><p>{}</p>".format(html.escape(message))
    if details:
        html_details = "<p>Details:</p><p>{}</p>".format(html.escape(details))
        html_message += html_details
    return "<html><body>{}</body></html>".format(html_message)
```

```python
def render_notification(title, message, level='info'):
    import html
    levels = {
        'info': 'info',
       'success':'success',
        'warning': 'warning',
        'error': 'danger'
    }
    if level not in levels:
        raise ValueError("Invalid level. Must be one of: {}".format(', '.join(levels.keys())))

    level_class = levels[level]
    return (
        "<div class='notification {}'>"
        "<h2>{}</h2>"
        "<p>{}</p>"
        "</div>".format(
            level_class,
            html.escape(title),
            html.escape(message)
        )
    )
```

