import html

def render_user_list(users):
    html_table = "<table>\n"
    html_table += "<tr><th>Name</th><th>Email</th><th>Role</th></tr>\n"
    for user in users:
        if 'name' in user and 'email' in user and 'role' in user:
            html_table += f"<tr><td>{html.escape(user['name'])}</td><td>{html.escape(user['email'])}</td><td>{html.escape(user['role'])}</td></tr>\n"
        else:
            raise ValueError("Invalid user dictionary")
    html_table += "</table>"
    return html_table
```

