def render_notification(title, message, level='info'):
    if level == 'info':
        color = 'blue'
    elif level =='success':
        color = 'green'
    elif level == 'warning':
        color = 'orange'
    elif level == 'error':
        color ='red'
    else:
        raise ValueError('Invalid level')

    return f'<div style="background-color: #ccc; padding: 10px; border-radius: 5px; margin-bottom: 10px;">' \
           f'<h3 style="color: {color}; margin-bottom: 5px;">{title}</h3>' \
           f'<p style="color: {color};">{message}</p>' \
           '</div>'
```

